INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, $s$united-states-connecticut$s$, 1, $s$United States$s$, $s$US$s$, $s$Connecticut$s$, $s$📍Mystic, Just a Quick, But Memorable, Pause! ⏳📸$s$, $s$Uncovering Coastal Charm & Maritime Magic! ✨⚓$s$, $s$📍Mystic, Connecticut$s$, $s$Discovering Mystic: A Charming Detour on the Way to Providence. Did you know that the Mystic River Bascule Bridge, which you'll likely cross while driving through Mystic, opens on average 2,200 times yearly? That's almost six times a day!$s$, $s$Our Enchanting Stop in Mystic, CT! ⚓🍕✨$s$, $s$aroundtheworld50s/blog/united-states-connecticut/1/IMG_0018$s$, $s$💥 New England - Insider Tips ⁉️: Your Key to an Unforgettable Trip (read more...)$s$, $s$united-states-connecticut$s$, $s$published$s$, '2025-07-13T00:00:00.000Z'::timestamptz, '2025-07-13T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, 0, $s$text$s$, $s${"html":"On our journey north, a spontaneous, we made a detour led us to the enchanting coastal town of Mystic, Connecticut! Don't let \"quick stop\" fool you – this place isn't just a dot on the map; it's a vibrant tapestry of history, marine life, and undeniable New England charm, making it the perfect, enriching interlude on any road trip.\n\nWe stopped at the 📌 Hoxie Scenic Overlook for breathtaking views, to capture the panoramic vista of the Mystic River, the iconic Bascule Bridge, the sprawling Mystic Seaport Museum, and the quaint, historic village nestled along the water. It's the absolute perfect spot to capture that postcard-perfect photo of this charming New England town. 📸\n\nWhile its fame might be tied to \"Mystic Pizza\" 🍕 (and yes, you absolutely should grab a slice – it's a rite of passage!), the town offers so much more profound insight into its maritime soul.\n\nThe Mystic River flows right through the heart of it. The star attraction here is undoubtedly the Mystic Bascule Bridge. Don't just walk over it – wait for it to lift! Watching this historic drawbridge gracefully rise to let tall ships and pleasure boats pass. The streets themselves are a delight, lined with independent boutiques, art galleries showcasing local talent, and cozy cafes. It's the perfect place to browse for unique souvenirs, grab a coffee, and just soak in the laid-back, nautical atmosphere.\nAlthough we didn't visit the famous Mystic Seaport Museum this time, I highly recommend setting aside a couple of hours for it, as we had an incredible experience on a previous occasion. It's an immersive living history village with historic ships. ⛵🕰️ Or, if you're traveling with kids, the Mystic Aquarium is a fantastic option (💥you can often buy a combined ticket for both attractions!). Kids especially love seeing the beluga whales and other marine life up close! 🐳🐠"}$s$::jsonb),
  ($s$f7283f99-3eaf-4272-af7c-e78d55ea7b1b$s$, 1, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-connecticut/1/IMG_0016","aroundtheworld50s/blog/united-states-connecticut/1/IMG_0019","aroundtheworld50s/blog/united-states-connecticut/1/IMG_0018","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9878","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9879","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9877","aroundtheworld50s/blog/united-states-connecticut/1/IMG_9876"]}$s$::jsonb);
